const fs=require('node:fs'),os=require('node:os'),path=require('node:path'),request=require('supertest');
const {createAuthenticatedActionApp}=require('./authenticated-app.cjs');
const {loadCatalog}=require('./knowledge-catalog.cjs');
const {FORMAT}=require('./action-state.cjs');
const crypto=require('node:crypto');
let directory,app,alice,bob,owner,source,revision,created,visible;
async function save(){const previous=(await alice.get('/api/action-state')).body;const result=await alice.put('/api/action-state').set('If-Match',previous.revision).send({format:FORMAT,data:source});expect(result.status).toBe(200);revision=result.body.revision}
beforeEach(async()=>{
 directory=fs.mkdtempSync(path.join(os.tmpdir(),'dianliang-owned-tutorial-history-'));app=createAuthenticatedActionApp({dataDir:directory,reviewDirectory:path.join(directory,'assets'),rateLimitEnabled:false}).app;alice=request.agent(app);bob=request.agent(app);owner=(await alice.post('/api/register').send({name:'history-alice',password:'test-only-2026'})).body.user.id;await bob.post('/api/register').send({name:'history-bob',password:'test-only-2026'});
 const method=id=>({id,title:id,author:'history-alice',versions:[{number:1,created:0,content:'ALICE-PRIVATE-STEPS-'+id,five:'先做一小步。',resource:'',resourceLinks:[{label:'材料',url:'https://example.com/material',affiliate:true,optional:false}]}]}),catalog={...loadCatalog().nodes.find(n=>n.originId==='eq'),id:'eq',version:1,methods:[method('catalog-method')]},personal={id:'my-goal',title:'私人历史目标',goal:'保留完整私人目标。',five:'先画三条线。',domain:'创造',branch:'个人',ownership:'personal',visibility:'private',version:1,methods:[method('private-method')]};
 source={schema:1,activeId:null,habitId:'h',habits:[{id:'h',name:'阅读',formedAt:null}],events:[],templates:{},nodes:[catalog,personal],lights:[]};await save();expect((await alice.post('/api/review-private-targets').set('If-Match',revision).send({nodeId:'my-goal',sourceVersion:1})).status).toBe(201);
 created=[];for(const [nodeId,methodId] of [['eq','catalog-method'],['my-goal','private-method']]){const r=await alice.post('/api/review-method-publications').set('If-Match',revision).send({nodeId,methodId,sourceVersion:1,visibility:'private'});expect(r.status).toBe(201);created.push(r.body.tutorial)}
 visible=(await alice.post('/api/review-target-sharing').set('If-Match',revision).send({nodeId:'my-goal',sourceVersion:1,action:'publish',consent:true})).body.node;
 const modern=await alice.post('/api/tutorials').send({treeId:visible.treeId,nodeId:visible.id,targetVersion:visible.version,title:'个人公开目标私人教程',method:'ALICE-VISIBLE-PRIVATE-STEPS',startAction:'从原目标开始。',visibility:'private'});expect(modern.status).toBe(201);created.push(modern.body.tutorial);
 const legacy=await alice.post('/api/tutorials').send({treeId:'k9-math',nodeId:'linear-equation',title:'旧目录资料',method:'LEGACY-ALICE-STEPS',visibility:'private'});expect(legacy.status).toBe(201);created.push(legacy.body.tutorial);await bob.post('/api/tutorials').send({treeId:'k9-math',nodeId:'linear-equation',title:'另一账号私人资料',method:'BOB-PRIVATE-STEPS',visibility:'private'});
});
afterEach(()=>{if(!path.resolve(directory).startsWith(path.resolve(os.tmpdir())+path.sep))throw Error('Unexpected fixture');fs.rmSync(directory,{recursive:true,force:true})});
it('exports independent action, all own knowledge histories and receipts with a cutoff copy while live data is untouched',async()=>{
 source.activeId='active';source.events=[{id:'active',name:'持续行动',startedAt:1000,endedAt:null,segments:[{start:1000,end:null}],steps:[],stepDone:{},draft:'ACTIVE-PRIVATE-DRAFT',notes:[{id:'note',text:'本人的单次笔记',at:1100}]}];const n=source.nodes[0],m=n.methods[0],v=m.versions[0];source.events.push({id:'practice',name:n.title,startedAt:0,endedAt:10,segments:[{start:0,end:10}],steps:[],stepDone:{},draft:'',notes:[],knowledge:{nodeId:n.id,nodeTitle:n.title,nodeGoal:n.goal,nodeVersion:n.version,methodId:m.id,methodTitle:m.title,version:v.number,content:v.content,five:v.five,resource:v.resource,resourceLinks:v.resourceLinks}});await save();expect((await alice.post('/api/review-practices').set('If-Match',revision).send({eventId:'practice',tutorialId:created[0].id,tutorialVersion:created[0].version,visibility:'private'})).status).toBe(201);const stateFile=path.join(directory,'action-states',owner+'.json'),before=fs.readFileSync(stateFile,'utf8');
 const png='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';expect((await alice.post('/api/records').send({treeId:'k9-math',nodeId:'linear-equation',text:'自己的私人实践',visibility:'private',images:[{mediaType:'image/png',dataUrl:'data:image/png;base64,'+png}]})).status).toBe(201);await bob.post('/api/records').send({treeId:'k9-math',nodeId:'linear-equation',text:'BOB-PRIVATE-RECORD',visibility:'private'});
 const r=await alice.get('/api/review-account-export');expect(r.status).toBe(200);expect(r.body.format).toBe('dianliang-service-archive/v1');expect(r.body.ownerId).toBe(owner);expect(r.body.service.tutorials.map(t=>t.id)).toEqual(created.map(t=>t.id));expect(r.body.service.methodBindings.bindings).toHaveLength(2);expect(r.body.service.privateTargets.bindings).toHaveLength(1);expect(r.body.service.practiceReceipts.ownerId).toBe(owner);expect(r.body.service.actionState.data.activeId).toBeNull();expect(r.body.service.actionState.data.events[0].segments[0].end).toBe(r.body.exportedAt);expect(r.body.service.actionState.data.events[0].endedAt).toBeNull();expect(r.body.service.actionState.data.events[0].draft).toBe('ACTIVE-PRIVATE-DRAFT');expect(fs.readFileSync(stateFile,'utf8')).toBe(before);
 const core=structuredClone(r.body);delete core.ok;delete core.integrity;expect(crypto.createHash('sha256').update(JSON.stringify(core)).digest('hex')).toBe(r.body.integrity.value);expect(r.body.service.sourceActionRevision).toBe(revision);expect(JSON.stringify(r.body)).not.toContain('BOB-PRIVATE');expect(JSON.stringify(r.body)).not.toContain('test-only-2026');expect(r.body).not.toHaveProperty('users');expect(r.body).not.toHaveProperty('sessions');
 expect(r.body.service.practiceReceipts.receipts).toHaveLength(1);expect(r.body.service.practiceReceipts.receipts[0].sourceSnapshot.nodeGoal).toBe(n.goal);expect(r.body.service.records.find(x=>x.text==='自己的私人实践').images[0].dataUrl).toBe('data:image/png;base64,'+png);
});
it('refuses a partial account export when an independent source is damaged and enforces account and Origin checks',async()=>{
 expect((await request(app).get('/api/review-account-export')).status).toBe(401);expect((await alice.get('/api/review-account-export').set('X-Action-Account','other-owner')).status).toBe(409);expect((await alice.get('/api/review-account-export').set('Origin','https://not-authorized.example')).status).toBe(403);
 const file=path.join(directory,'method-bindings',owner+'.json');fs.writeFileSync(file,'{damaged');const failed=await alice.get('/api/review-account-export');expect(failed.status).toBe(500);expect(failed.body.code).toBe('REVIEW_ARCHIVE_SOURCE_UNREADABLE');expect(failed.body).not.toHaveProperty('service');expect(fs.readFileSync(file,'utf8')).toBe('{damaged');
});
it('returns every own tutorial type and exact version bindings without manufacturing a legacy goal',async()=>{
 const r=await alice.get('/api/review-owned-tutorials');expect(r.status).toBe(200);expect(r.headers['cache-control']).toBe('no-store');expect(r.body.ownerId).toBe(owner);expect(r.body.tutorials.map(t=>t.id)).toEqual(created.map(t=>t.id));expect(r.body.tutorials.map(t=>t.kind)).toEqual(['catalog','personal-private','personal-public','unmapped']);
 const [catalog,privateGoal,personal,legacy]=r.body.tutorials;expect(catalog.targetSnapshots[0].target.goal).toBe(source.nodes[0].goal);expect(privateGoal.targetSnapshots[0].target.goal).toBe(source.nodes[1].goal);expect(personal.targetSnapshot.version).toBe(visible.version);expect(legacy.targetMappingStatus).toBe('unmapped');expect(legacy.targetSnapshots).toEqual([]);expect(legacy.versions[0].targetSnapshots).toEqual([]);expect(catalog.resources).toEqual(created[0].resources);expect(JSON.stringify(r.body)).not.toContain('BOB-PRIVATE-STEPS');expect(JSON.stringify((await bob.get('/api/review-owned-tutorials')).body)).not.toContain('ALICE-PRIVATE-STEPS');
});
it('retains both actual private goal definitions when the same tutorial content is saved against two target versions',async()=>{
 source.nodes[1].version=2;source.nodes[1].goal='后来确实保存的第二版私人目标。';await save();const current=(await alice.get('/api/review-private-targets')).body.current.find(t=>t.node.id===created[1].nodeId)|| (await alice.get('/api/review-private-targets')).body.current[0];
 const p=await alice.post('/api/review-private-targets').set('If-Match',revision).set('If-Target-Match',current.revision).send({nodeId:'my-goal',sourceVersion:2});expect(p.status).toBe(201);const saved=await alice.post('/api/review-method-publications').set('If-Match',revision).send({nodeId:'my-goal',methodId:'private-method',sourceVersion:1,visibility:'private'});expect(saved.status).toBe(200);
 const own=(await alice.get('/api/review-owned-tutorials')).body.tutorials.find(t=>t.id===created[1].id);expect(own.targetSnapshots.map(p=>p.target.goal)).toEqual(['保留完整私人目标。','后来确实保存的第二版私人目标。']);expect(own.versions).toHaveLength(1);expect(own.versions[0].targetSnapshots).toHaveLength(2);
});
it('keeps archived and withdrawn-target own histories readable while refusing forged actors and preserving damaged bindings',async()=>{
 expect((await alice.delete('/api/tutorials/'+created[3].id)).status).toBe(200);const sharing=(await alice.get('/api/review-target-sharing').query({nodeId:'my-goal'})).body;expect((await alice.post('/api/review-target-sharing').set('If-Match',revision).set('If-Target-Match',sharing.revision).send({nodeId:'my-goal',sourceVersion:1,action:'withdraw',consent:true})).status).toBe(200);
 const own=(await alice.get('/api/review-owned-tutorials')).body.tutorials;expect(own.find(t=>t.id===created[3].id).archived).toBe(true);expect(own.find(t=>t.id===created[2].id).targetSnapshot.goal).toBe(visible.goal);expect((await bob.get('/api/review-owned-tutorials').set('X-Action-Account',owner)).status).toBe(409);expect((await alice.get('/api/review-owned-tutorials').set('Origin','https://not-authorized.example')).status).toBe(403);expect((await request(app).get('/api/review-owned-tutorials')).status).toBe(401);
 const file=path.join(directory,'method-bindings',owner+'.json'),original=fs.readFileSync(file,'utf8');fs.writeFileSync(file,'{damaged');expect((await alice.get('/api/review-owned-tutorials')).status).toBe(500);expect(fs.readFileSync(file,'utf8')).toBe('{damaged');fs.writeFileSync(file,original);
 const tutorialFile=path.join(directory,'tutorials.json'),damaged=JSON.parse(fs.readFileSync(tutorialFile,'utf8'));damaged.find(t=>t.id===created[0].id).sourceOrigin.privateCredential='NOT-FOR-EXPORT';const bytes=JSON.stringify(damaged);fs.writeFileSync(tutorialFile,bytes);const rejected=await alice.get('/api/review-owned-tutorials');expect(rejected.status).toBe(500);expect(JSON.stringify(rejected.body)).not.toContain('NOT-FOR-EXPORT');expect(fs.readFileSync(tutorialFile,'utf8')).toBe(bytes);
});
